content.text:
569 commands (id — label [menu] (shortcut) params; * = undoable):
node.create* — Create layer {type: rectangle|ellipse|polygon|star|line|arrow|vector|text|frame|section|component|slice, x?, y? (relative to the parent frame; groups don't count), width?, height?, parent? (id; default: the page), index?, name?, text? (for text), path? (SVG path data for vector), props? {node.set keys}, select? (default true)}
frame.create* — Create frame {preset? (name from FRAME_PRESETS), x?, y?, width?, height?, parent?, name?, props?} (a preset without x/y lands to the right of the page's frames)
shape.rectangle* — Rectangle {x, y, width, height, parent?, props?}
shape.ellipse* — Ellipse {x, y, width, height, parent?, props?}
shape.polygon* — Polygon {x, y, width, height, parent?, props? {pointCount}}
shape.star* — Star {x, y, width, height, parent?, props? {pointCount, innerRadius}}
shape.line* — Line {x, y, width (length), parent?, props? {rotation}}
shape.arrow* — Arrow {x, y, width (length), parent?, props?}
text.create* — Text {text, x, y, parent?, width? (fixed width wraps), props? (fontSize, fontFamily, …)}
vector.create* — Vector {path (SVG path data) | points [[x,y],..], closed?, x?, y?, width?, height? (scale the path; one keeps its proportion), parent?, props?}
image.place* — Place image {data (base64) | path, x?, y?, width?, height?, parent?, mode? (fill|fit|crop|tile)} → {id, image, width, height, imageProfile (its embedded colour profile; null: taken as sRGB)}
frame.swapOrientation* — Swap orientation {ids?} (portrait ⇄ landscape: width and height trade places)
frame.presets — List frame presets {}
edit.undo — Undo [Edit] (Cmd+Z) {}
edit.redo — Redo [Edit] (Shift+Cmd+Z) {}
edit.delete* — Delete [Edit] (Delete) {ids?}
edit.duplicate* — Duplicate [Edit] (Cmd+D) {ids?, dx?, dy? (page offset; default: the offset of the last duplicate when ids are its copies, still selected; else top-level frames to the right with a 100 gap, everything else in place)}  a main component's copy is an instance of it (a variant stays a new variant in its set)
edit.copy — Copy [Edit] (Cmd+C) {ids?}
edit.cut* — Cut [Edit] (Cmd+X) {ids?}
edit.paste* — Paste [Edit] (Cmd+V) {parent?, x?, y? (page coordinates of the pasted top-left)}  a copied main component pastes as an instance of it within its file (cut ones, and pastes into other files, keep the component)
edit.pasteDesignLayers* — Paste design layers {html (the clipboard's HTML) | data (base64 of the clipboard's design data, at most 256 MB), parent?, x?, y?}  layers copied from another design app (a .fig canvas in the clipboard's HTML), read like a .fig file (best effort, with `warnings`), pasted as edit.paste pastes
edit.pasteOver* — Paste over selection [Edit] (Shift+Cmd+V) {}
edit.pasteReplace* — Paste to replace [Edit] (Shift+Cmd+R) {ids?}
edit.copyProperties — Copy properties [Edit] (Alt+Cmd+C) {id?}
edit.pasteProperties* — Paste properties [Edit] (Alt+Cmd+V) {ids?}
edit.findReplace* — Find and replace [Edit] (Cmd+F) {find, replace? (text layers), layerNames? (bool), select? (default true)}
edit.setDefaultProperties — Set default properties [Edit] {id?}
select.set — Select {ids: [..]}  (replace the selection)
select.add — Add to selection {ids}
select.remove — Remove from selection {ids}
select.layersAt — Layers at a point {x, y (page coordinates)} → {layers: [{id, name, type, depth}]} (every layer under the point, front-most first; what the context menu's Select layer lists)
select.all — Select all [Edit] (Cmd+A) {}
select.none — Select none [Edit] (Escape) {}
select.inverse — Select inverse [Edit] (Shift+Cmd+A) {}
select.area — Select area (Ctrl+Space) {x, y, width, height (page units; a marquee from x, y), add? (toggle like a Shift marquee), deep? (nested layers, like Cmd/Ctrl)} → {selection}; with no box: draw one from the keyboard in the app (arrows move it, Cmd/Ctrl+arrows or Shift+arrows size it, Enter selects, Escape cancels)
select.children — Select children [Object/Select layer] (Enter) {}
select.parent — Select parent [Object/Select layer] (Shift+Enter) {}
select.next — Select next sibling [Object/Select layer] (Tab) {}
select.previous — Select previous sibling [Object/Select layer] (Shift+Tab) {}
select.matching — Select matching layers [Edit] (Alt+Cmd+A) {}
select.sameFill — Select same fill [Edit/Select all with same] {}
select.sameStroke — Select same stroke [Edit/Select all with same] {}
select.sameEffect — Select same effect [Edit/Select all with same] {}
select.sameText — Select same text properties [Edit/Select all with same] {}
select.sameFont — Select same font [Edit/Select all with same] {}
select.sameInstance — Select same instance [Edit/Select all with same] {}
select.sameProperties — Select same properties [Edit/Select all with same] {}
select.byName — Select layers by name {query, page? (default current; "all" for every page)}
transform.nudge* — Nudge {dx, dy, big? (use the big nudge amount)} (auto layout children move one place instead: along the flow, between wrapped rows, to the next grid cell, or into the neighbouring nested auto layout frame)
transform.nudgeSize* — Resize by nudge {dw, dh, big?} (grow or shrink the selection by the nudge amount, top-left fixed)
object.rename* — Rename [Object] (Cmd+R) {ids?, name?} (without a name: rename the layer inline in the layers panel)
object.batchRename* — Batch rename [Object] {ids?, find? (match; empty: none), regex? (find is a regular expression), replace? (for each match), name? (pattern for the whole name), start? (where $n starts and $N stops; default 1)} codes in replace and name: $& current name (or the match), $` and $' text before and after the match, $1…$9 groups, $n up, $N down, $nnn padded; layers are numbered in stacking order, bottom first
object.toggleVisible* — Show/Hide selection [Object] (Shift+Cmd+H) {ids?, visible?}
object.toggleLock* — Lock/Unlock selection [Object] (Shift+Cmd+L) {ids?, locked?}
object.hideOthers* — Hide other layers [Object] {}
object.opacityKeys* — Opacity from number keys {digits ("1"…"9": 10%…90%, "0": 100%; two digits: that percentage, "45" is 45%), ids?}
object.removeFill* — Remove fill [Object] (Alt+/) {ids?}
object.removeStroke* — Remove stroke [Object] (Shift+/) {ids?}
object.swapFillStroke* — Swap fill and stroke [Object] (Shift+X) {ids?}
layers.collapseAll — Collapse layers [Object] (Alt+L) {}
node.set* — Set properties name, visible, locked, opacity (0-1), blend, x, y (relative to the parent frame; groups don't count), width, height, rotation (degrees), fills (paints or colours; gradients as {type: linearGradient|radialGradient|angularGradient|diamondGradient, stops: ["#hex", ...], from?, to?} too), fill (colour), strokes, stroke (colour), strokeWeight, strokeAlign (inside|center|outside), strokeSides [t,r,b,l], strokeTopWeight / strokeRightWeight / strokeBottomWeight / strokeLeftWeight (one side; turns on individual strokes), strokeCap / startCap / endCap, strokeJoin, miterAngle (degrees: sharper joins bevel; or miterLimit as a ratio), dashes [..], widthProfile (preset uniform|wedge|taper|eye|rounded|pinch, [[t, scale], ...] or null), brush (preset id, {preset, spacing, sizeJitter, rotationJitter, scatter, seed} or null), cornerRadius (n or [tl,tr,br,bl]), cornerSmoothing (0-1), effects, clip, isMask, layout (null|horizontal|vertical|grid|{...}), gap, crossGap, padding (n or [t,r,b,l]), paddingTop/Right/Bottom/Left, mainAlign (min|center|max, or the auto gaps spaceBetween|spaceAround|spaceEvenly), crossAlign (min|center|max|baseline: first text baselines, horizontal layouts), contentAlign (wrapped lines: auto = packed where crossAlign says | spaceBetween), wrap (rows of a horizontal layout, columns of a vertical one), strokesIncluded (the frame's inside stroke takes up space), reverseZ (canvas stacking: true = first on top), columnGap / rowGap (aliases of gap / crossGap), gridColumns, gridRows, columnTracks / rowTracks ([120 | "1fr" | "auto" | {sizing, value}]), gridColumn / gridRow (0-based cell anchor, null = auto), gridColumnSpan, gridRowSpan, gridAlignH / gridAlignV (a grid child's alignment in its cell: min|center|max, auto/null = the frame's), sizingH / sizingV (fixed|hug|fill), absolute (ignore auto layout; follows constraints), minWidth, maxWidth, minHeight, maxHeight (null removes), constraints {horizontal, vertical}, grids, exports, characters, fontFamily, fontStyle, fontSize, lineHeight (auto|px|"150%"), letterSpacing (px|"2%"), textAlign (left|center|right|justified), textAlignVertical, textAutoResize (widthAndHeight|height|none|truncate), textDecoration, textDecorationStyle (solid|dotted|wavy), textDecorationThickness / textDecorationOffset (auto|px|"10%" of the font size; the offset runs from the baseline down to an underline's top edge), textDecorationSkipInk (underlines break around descenders), textDecorationColor (colour, or auto/null: the text's), textCase (original|upper|lower|title|smallCaps), paragraphSpacing, paragraphIndent, listStyle (none|bulleted|numbered; with start/end: the paragraphs those chars touch), indentation (list nesting level 0-8, same range rule), listSpacing (px between list items, in place of paragraphSpacing), hangingPunctuation, hangingList (markers outside the box), leadingTrim (vertical trim: none|capHeight), maxLines, features ({tag: bool}, e.g. {"liga": false, "tnum": true}), fontVariations / variationSettings ({axis: number}, e.g. {"wght": 550, "wdth": 85}; null = none), pointCount, innerRadius, arcStart, arcSweep, arcInner, booleanOperation (a boolean group's operation, or an operand's own; null: the group's), operandOperation (a layer in a boolean group: how it combines with the operands below it; null: the group's), constrainProportions, description, interactions, overflow, pluginData {k: v}
node.get — Get layer {id}
node.reparent* — Move layer into {ids?, parent, index?}
node.reorder* — Reorder layer {id, index}
fill.add* — Add fill {ids?, paint? (default #D9D9D9 or white for frames)}
stroke.add* — Add stroke {ids?, paint? (default black)}
fill.remove* — Remove fill {ids?, index}
stroke.remove* — Remove stroke {ids?, index}
fill.set* — Set fill {ids?, index?, paint | color, opacity?, visible?, blend?}
stroke.set* — Set stroke {ids?, index?, paint | color, opacity?, visible?, blend?}
fill.pattern* — Pattern fill {source (layer id), ids?, index? (default the top fill), tile? (grid|horizontalHex|verticalHex), scale? (1 = the source's size), spacing? [x, y], align? (start|center|end), opacity?}  the source layer tiled; it updates as the source changes
stroke.widthProfile* — Width profile {ids?, preset? (uniform|wedge|taper|eye|rounded|pinch) | points? [[t (0-1 along each subpath), scale (× stroke weight)], ...]} — none = uniform
stroke.brush* — Brush {ids?, preset (taper|ink|ribbon|bristle: stretched along the path; dots|stars|confetti|leaves: scattered along it | null: plain), spacing? (× weight), sizeJitter? (0-1), rotationJitter? (0-1), scatter? (0-4 × weight), seed?}  layers without a stroke get a black one
effect.add* — Add effect {ids?, type? (dropShadow|innerShadow|layerBlur|backgroundBlur|noise|texture|glass), effect? {..}}
effect.remove* — Remove effect {ids?, index}
effect.set* — Set effect {ids?, index, effect {..}}
grid.add* — Add layout grid {ids?, grid? {kind: grid|columns|rows, ..}}
grid.remove* — Remove layout grid {ids?, index}
export.add* — Add export setting {ids?, setting? {size: 2x|512w|512h|{by: scale|width|height, value}, suffix?, format?: png|jpg|svg|pdf|webp, bleed? (PDF: points, or with a unit: "3mm", "0.125in", "9pt"), cropMarks?, bleedMarks?, cmyk? (PDF print options)}} (without a setting: 1x, then one scale step up with an "@2x"-style suffix)
export.update* — Edit export setting {ids?, index, size? (2x|512w|512h|{by, value}), suffix?, format? (png|jpg|svg|pdf|webp), bleed? (PDF: points, or with a unit: "3mm", "0.125in", "9pt"), cropMarks?, bleedMarks?, cmyk? (PDF print options)}
export.remove* — Remove export setting {ids?, index}
command.batch — Run several commands {label?, commands: [{command, params}]} (one undo step)
edit.repeat* — Repeat last command {}
fill.move* — Move fill {ids?, from, to} (indices in the fill list, bottom first)
stroke.move* — Move stroke {ids?, from, to} (indices in the stroke list, bottom first)
effect.move* — Move effect {ids?, from, to} (indices in the effect list, bottom first)
grid.move* — Move layout grid {ids?, from, to} (indices in the layout grid list, bottom first)
selection.colors — Selection colors {ids?} → {colors: [{paint, targets}]}; includes descendants and text ranges
selection.setPaint* — Change selection color {targets: [{id, fills, index, range: [start,end] | null}], paint}
selection.applyColorStyle* — Apply selection color style {targets, style}; applies the color style to matching fill/stroke lists (text ranges keep typography)
selection.selectColor — Select layers with color {targets} → {ids}; selects the layers owning these paint slots
align.left* — Align left [Arrange] (Alt+A) {ids?}
align.hcenter* — Align horizontal centers [Arrange] (Alt+H) {ids?}
align.right* — Align right [Arrange] (Alt+D) {ids?}
align.top* — Align top [Arrange] (Alt+W) {ids?}
align.vcenter* — Align vertical centers [Arrange] (Alt+V) {ids?}
align.bottom* — Align bottom [Arrange] (Alt+S) {ids?}
distribute.horizontal* — Distribute horizontal spacing [Arrange] (Alt+Shift+H) {ids?, spacing?}
distribute.vertical* — Distribute vertical spacing [Arrange] (Alt+Shift+V) {ids?, spacing?}
arrange.spacing* — Spacing {ids?, horizontal?, vertical?, fromGesture?} (page units; fromGesture uses the interaction snapshot)
arrange.tidy* — Tidy up [Arrange] (Ctrl+Alt+Shift+T) {ids?, spacing?}
arrange.reorder* — Reorder selection {ids?, source, target, swap?, fromGesture?} (insert at target's visual slot; no hierarchy changes)
arrange.packH* — Pack horizontal [Arrange] {ids?}
arrange.packV* — Pack vertical [Arrange] {ids?}
arrange.roundToPixels* — Round to pixels [Arrange] {ids?}
arrange.front* — Bring to front [Object] (Shift+Cmd+]) {ids?}
arrange.forward* — Bring forward [Object] (Cmd+]) {ids?}
arrange.backward* — Send backward [Object] (Cmd+[) {ids?}
arrange.back* — Send to back [Object] (Shift+Cmd+[) {ids?}
object.flipH* — Flip horizontal [Object] (Shift+H) {ids?} (in vector edit mode without ids: the selected points)
object.flipV* — Flip vertical [Object] (Shift+V) {ids?} (in vector edit mode without ids: the selected points)
object.rotate180* — Rotate 180° [Object] {ids?} (in vector edit mode without ids: the selected points)
object.rotateLeft* — Rotate 90° left [Object] {ids?} (in vector edit mode without ids: the selected points)
object.rotateRight* — Rotate 90° right [Object] {ids?} (in vector edit mode without ids: the selected points)
transform.move* — Move {ids?, dx, dy}  (page units)
transform.moveTo* — Move to {ids?, x, y} (page coordinates of the selection's top-left)
transform.rotate* — Rotate {ids?, degrees, cx?, cy? (pivot, page coords; default the selection's rotation origin, else its centre)}
transform.rotationOrigin — Move rotation origin (Alt+R) {on? (default: toggles)} — shows the selection's rotation origin to drag (Escape hides it); not saved
transform.setRotationOrigin — Set rotation origin {x, y (page coords) | reset: true} — the point the selection turns about (default its centre); kept while the selection lasts, not saved
transform.scale* — Scale {ids?, factor, cx?, cy? (pivot; default top-left)} — scales size, strokes, effects, text (the K tool)
transform.resize* — Resize {ids?, width?, height?, anchor? (tl|t|tr|l|c|r|bl|b|br)}
object.group* — Group selection [Object] (Cmd+G) {ids?, name?}
object.ungroup* — Ungroup selection [Object] (Shift+Cmd+G) {ids?}
object.frameSelection* — Frame selection [Object] (Alt+Cmd+G) {ids?, name?}
object.removeFrame* — Remove frame [Object] {ids?}
object.convertToGroup* — Convert to group {ids?} (frames become groups in place, their layers staying where they are; what only a frame has goes: auto layout, fills, strokes, corner radius, clipping, layout grids, guides and scrolling. Groups are left alone; instances, main components, layers inside instances and empty frames are refused)
object.convertToFrame* — Convert to frame {ids?} (groups become frames of the same box in place, their layers staying where they are: no fill, not clipping; sections become frames that keep their fill and don't clip. Frames are left alone; instances, main components, layers inside instances and sections holding sections are refused)
object.convertToSection* — Convert to section {ids?} (frames on the page or in a section become sections in place, keeping their fill and layers; what only a frame has goes: auto layout, clipping, layout grids, guides and scrolling. Sections are left alone; nested frames, instances and main components are refused)
object.wrapInSection* — Wrap in new section {ids?, name?} (layers on the page or in a section; the section wraps them with some room)
object.resizeToFit* — Resize to fit [Object] (Alt+Shift+Cmd+R) {ids?} (frames, sections and components shrink or grow to their contents; the contents stay put)
object.mask* — Use as mask [Object] (Ctrl+Alt+M) {ids?}
object.releaseMask* — Release mask [Object] {ids?}
bool.union* — Union selection [Object/Boolean groups] (Alt+Shift+U) {ids?} — layers inside boolean groups: sets their own operation (how each combines with the operands below it); one boolean group: sets its operation (every operand follows it); otherwise wraps the layers in a new boolean group
bool.subtract* — Subtract selection [Object/Boolean groups] (Alt+Shift+S) {ids?} — layers inside boolean groups: sets their own operation (how each combines with the operands below it); one boolean group: sets its operation (every operand follows it); otherwise wraps the layers in a new boolean group
bool.intersect* — Intersect selection [Object/Boolean groups] (Alt+Shift+I) {ids?} — layers inside boolean groups: sets their own operation (how each combines with the operands below it); one boolean group: sets its operation (every operand follows it); otherwise wraps the layers in a new boolean group
bool.exclude* — Exclude selection [Object/Boolean groups] (Alt+Shift+E) {ids?} — layers inside boolean groups: sets their own operation (how each combines with the operands below it); one boolean group: sets its operation (every operand follows it); otherwise wraps the layers in a new boolean group
bool.flatten* — Flatten boolean [Object/Boolean groups] {ids?}
vector.flatten* — Flatten [Object] (Alt+Shift+F) {ids?}
vector.outlineStroke* — Outline stroke [Object] (Alt+Cmd+O) {ids?}
layout.add* — Add auto layout [Object] (Shift+A) {ids?, direction? (horizontal|vertical|grid)}
layout.remove* — Remove auto layout [Object] (Alt+Shift+A) {ids?}
layout.suggest* — Suggest auto layout [Object] (Ctrl+Alt+Shift+A) {ids?}
object.moveToPage* — Move to page [Object] {ids?, page}
object.setThumbnail* — Set as thumbnail [Object] {id?}
object.rasterize* — Rasterize selection [Object] {ids?, scale? (default 2)}
vector.reverse* — Reverse path direction [Vector] {ids?}
vector.simplify* — Simplify vector [Vector] {ids?, tolerance?}
vector.offset* — Offset path [Vector] {ids?, offset}
vector.join* — Join selection [Vector] (Cmd+J) {ids?} (in vector edit mode: joins the selected points)
vector.smoothJoin* — Smooth join selection [Vector] (Shift+Cmd+J) {ids?} (in vector edit mode: joins the selected points smoothly)
section.toggleContents* — Hide/Show section contents {ids?, hidden? (default: hide unless all are hidden)} (a hidden section shows only its name and outline; its layers aren't drawn or hit)
dev.resolveChange* — Resolve change {ids?, reason?} (ready-for-dev frames and sections that changed since they were marked go back to Ready for dev; the reason is kept)
dev.compare — Compare changes {id? (default the first selected layer), show? (open the compare view in the app)} → {id, name, changed, snapshot, added, removed, modified, truncated, changes: [{id, name, type, change: added|removed|changed, depth, layers, properties?: [{section, property, before, after, text}]}]}  what changed in a ready-for-dev frame or section since it was marked (`snapshot` is false when that isn't known: a file from before snapshots were kept)
dev.focus — Focus view {id? (a top-level frame or section; default the selection) | direction?: next|previous (the next ready-for-dev one, across pages)} → {id, name, page, index, count}  show only that layer on the canvas (Escape or `dev.unfocus` ends it)
dev.unfocus — Exit focus view {} → {focused: false}
layout.setTrack* — Set grid track size {ids?, axis: columns|rows, index (0-based), sizing: fixed|hug|fill, value? (fixed: px, default the track's current size; fill: fr, default 1)}
file.new — New design file [File] (Cmd+N) {name?}
file.open — Open [File] (Cmd+O) {path | data (base64) + name (tells the format; opens as a new unsaved document), variables? (REST: the local variables JSON as an object, JSON text or a path; default `<name>.variables.json` or `variables.json` next to the file)} (.figcraft, .json: FigCraft or REST API file JSON, .fig (best effort), .svg, .png, .jpg …); REST and .fig imports return `warnings`; a file opened anew returns `summary` {name, pages, layers, images} (one that was already open just returns its `index`)
file.openRecent — Open recent [File] {path? | index? (into the list), clear? (forget them all), remove? (a path: forget that one)}  opens a recent file; a file that no longer exists is dropped from the list. Returns the list, newest first: {files: [{path, name, exists}]} (opening returns what `file.open` does)
file.save — Save [File] (Cmd+S) {path?} (programmatic saves need a path the first time); a .fig path writes an experimental export copy of the shown document with `warnings`, keeping the native path, unsaved changes and version preview
file.saveAs — Save as [File] (Shift+Cmd+S) {path} (no extension adds .figcraft); a .fig path writes an experimental export copy of the shown document with `warnings`, keeping the native path, unsaved changes and version preview
file.export — Export [File] (Shift+Cmd+E) {ids? (default selection, else the page), format? (png|jpg|svg|pdf|webp, or fig: the whole file as .fig, experimental, with `warnings` for what was left out; other apps may not open every file), scale? (default 1) | size? (2x|512w|512h or {by: scale|width|height, value}: a scale, or a width or height in pixels), path? (else returns base64 `data`), bleed? (PDF: points, or with a unit: "3mm", "0.125in", "9pt"), cropMarks?, bleedMarks?, cmyk? (PDF print options)}
file.exportLayers — Export layers {ids? (default the selection, else every layer on the page with export settings), assets? (true: the Inspect tab's assets in and under them instead: layers with export settings, icons as SVG, images as PNG), dir? (folder to write into; else each file comes back as base64 `data`), bleed? (PDF: points, or with a unit: "3mm", "0.125in", "9pt"), cropMarks?, bleedMarks?, cmyk? (PDF print options): for every PDF instead of each setting's own}  every layer once per export setting, named `<layer><suffix>.<format>` ("@2x" when a scaled export has no suffix; repeats get " 2"; slashes in a layer name make folders). Returns {files: [{name, id, bytes, path | data}], skipped (layers without settings)}
file.exportSvg — Export selection as SVG [File] {ids?, path?}
file.exportFramesPdf — Export frames to PDF [File] {path?, page? (page id, default the current page), bleed? (PDF: points, or with a unit: "3mm", "0.125in", "9pt"), cropMarks?, bleedMarks?, cmyk? (PDF print options)}  every top-level frame in reading order, one PDF page each; returns base64 `data` without a path
file.import* — Import [File] (Shift+Cmd+I) {path | data (base64) + name, x?, y?, center? (SVG: centre it on x, y), variables? (REST: the local variables JSON as an object, JSON text or a path)}  SVG becomes an editable frame (shapes, text, gradients, masks, effects; with `warnings` for what it left out), images become image layers, .figcraft, REST API file JSON and .fig pages are appended with their variables and flows (REST and .fig: with `warnings`; those return `summary` {name, pages, layers, images} of the file read)
file.placeImage* — Place image [File] (Shift+Cmd+K) {path | data, x?, y?}
file.close — Close tab [File] (Cmd+W) {index?, force? (discard unsaved changes)}
file.moveTab — Move tab {from, to} (indices among open documents)
file.recover — Recover file {path}  open a recovery copy (written while the app runs, read back after a crash) as a document with unsaved changes and no path: saving asks where → {index}
file.rename* — Rename file [File] {name}
file.colorProfile* — Color profile [File] {profile?: srgb|displayP3, convert? (default true: convert colour values so colours keep their appearance; false: keep the values and reinterpret them)}  without `profile`, returns the current one (and the app opens the dialog). Returns {profile, changed}
file.duplicate — Duplicate file [File] {}
file.revert — Revert to saved [File] {}  leave the live session first, if any
file.saveVersion — Save to version history [File] (Alt+Cmd+S) {name?, description?}  snapshot the document into the file's version history (on a branch tab: the branch's own history; kept when the file is saved); returns the version
file.versionHistory — Show version history [File] {}  opens the panel; returns the versions like `version.list`
version.list — List versions {}  the version history, oldest first: [{id, index, name, description, time (Unix seconds), auto?, previewing?}]
version.restore* — Restore version {id | index}  replace the design with the version (one undo step; the file name and the comments stay; the design as it was is kept in the history first, unless a version of it was just saved or restored)
version.rename — Rename version {id | index, name, description?}  a titled autosave becomes a named version
version.delete — Delete version {id | index}
version.preview — View version {id | index}  show the version on the canvas in place of the document (read-only; `version.restore` keeps it, `version.exitPreview` goes back)
version.autosave — Autosave version {}  save an automatic checkpoint when the document has unsaved changes since the last version (with `pref.autoSave` on: changes made since it was opened); the app does this every 30 minutes; keeps the newest 20 autosaves → {saved, version?}
version.exitPreview — Back to current version {}  end a version preview
version.duplicate — Duplicate version {id | index}  open the version as a new document; returns its tab `index`
doc.switch — Switch document {index}
doc.nextTab — Next tab (Ctrl+Tab) {}
doc.previousTab — Previous tab (Ctrl+Shift+Tab) {}
doc.list — List documents {}
doc.home — Home {}
page.add* — Add page {name?} (a name starting with a hyphen adds a divider)
page.select — Go to page {id | index}
page.rename* — Rename page {id?, name} (an empty page named with a leading hyphen becomes a divider)
page.delete* — Delete page {id?}
page.duplicate* — Duplicate page {id?}
page.move* — Move page {id?, index}
page.setBackground* — Page background {id?, color}
page.list — List pages {}
guide.add* — Add guide {vertical (bool), offset, frame? | page?} → {index}
